SELECT type_name, expected_lifetime_years 
FROM asset_types 
WHERE expected_lifetime_years > 30;

SELECT sr.reading_id, sr.asset_id, sr.reading_time, sr.sensor_type, sr.reading_value, sr.unit, sr.alarm_flag 
FROM sensor_readings sr 
WHERE sr.sensor_type = 'voltage' AND sr.alarm_flag = 1;

SELECT asset_id, asset_name, capacity_mw 
FROM assets 
WHERE capacity_mw > 100;

SELECT DISTINCT manufacturer 
FROM asset_types 
WHERE voltage_class = '230kV';

SELECT reading_id, asset_id, reading_time, sensor_type, reading_value, unit, alarm_flag 
FROM sensor_readings 
WHERE sensor_type = 'load' AND reading_value > 80 AND unit = 'MW';

SELECT asset_id, asset_name, install_date 
FROM assets 
WHERE install_date >= '2020-01-01';

SELECT unit, COUNT(*) AS reading_count
FROM sensor_readings
GROUP BY unit;

SELECT ROUND(AVG(s.reading_value), 0) AS avg_voltage_kv
FROM sensor_readings s
WHERE s.sensor_type = 'voltage' AND s.unit = 'kV';

SELECT work_order_id, asset_id, assigned_technician_id, priority, status, scheduled_date, completed_date, fault_code 
FROM work_orders 
WHERE scheduled_date LIKE '2024-07%';

SELECT log_id, work_order_id, technician_id, action_type, started_at, ended_at, notes, parts_cost 
